BEGIN TRANSACTION READ ONLY;
WITH actual AS (SELECT json_build_object(
 'table',(SELECT json_build_object('owner',pg_get_userbyid(relowner),'rls',relrowsecurity) FROM pg_class WHERE oid='public.properties'::regclass),
 'columns',(SELECT json_agg(json_build_object('column',column_name,'type',data_type,'udt',udt_name,'nullable',is_nullable,'default',column_default,'precision',numeric_precision,'scale',numeric_scale) ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema='public' AND table_name='properties'),
 'constraints',(SELECT json_agg(json_build_object('table',conrelid::regclass::text,'name',conname,'definition',pg_get_constraintdef(oid)) ORDER BY conrelid::regclass::text,conname) FROM pg_constraint WHERE conrelid='public.properties'::regclass OR confrelid='public.properties'::regclass),
 'policies',(SELECT json_agg(json_build_object('name',policyname,'roles',roles,'command',cmd,'using',qual,'check',with_check) ORDER BY policyname) FROM pg_policies WHERE schemaname='public' AND tablename='properties'),
 'triggers',(SELECT json_agg(json_build_object('table',t.tgrelid::regclass::text,'name',t.tgname,'function',p.proname,'definition_md5',md5(pg_get_triggerdef(t.oid)),'body_md5',md5(p.prosrc)) ORDER BY t.tgrelid::regclass::text,t.tgname) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE NOT t.tgisinternal AND t.tgrelid IN ('public.properties'::regclass,'public.property_images'::regclass,'public.property_floor_plans'::regclass,'public.property_features'::regclass,'public.property_amenities'::regclass,'public.viewing_requests'::regclass,'public.enquiries'::regclass)),
 'grants',(SELECT json_agg(json_build_object('role',grantee,'privilege',privilege_type) ORDER BY grantee,privilege_type) FROM information_schema.table_privileges WHERE table_schema='public' AND table_name='properties' AND grantee IN ('PUBLIC','anon','authenticated','service_role')),
 'role_permissions',(SELECT json_agg(json_build_object('role',r.name,'permission',p.name) ORDER BY r.name,p.name) FROM public.role_permissions rp JOIN public.roles r ON r.id=rp.role_id JOIN public.permissions p ON p.id=rp.permission_id WHERE p.name IN ('properties.view','properties.manage')),
 'legacy_aggregates',(SELECT json_build_object('rented_rows_exist',coalesce(bool_or(status='rented'),false),'negative_numeric_values_exist',coalesce(bool_or(price<0 OR bedrooms<0 OR bathrooms<0 OR floor_area<0 OR land_area<0),false),'title_max',coalesce(max(char_length(title)),0),'slug_max',coalesce(max(char_length(slug)),0),'description_max',coalesce(max(char_length(description)),0),'property_type_max',coalesce(max(char_length(property_type)),0),'listing_type_max',coalesce(max(char_length(listing_type)),0),'location_max',coalesce(max(char_length(location)),0),'address_max',coalesce(max(char_length(address)),0),'city_max',coalesce(max(char_length(city)),0),'region_max',coalesce(max(char_length(region)),0)) FROM public.properties),
 'last_migration',(SELECT max(version) FROM supabase_migrations.schema_migrations)
) AS evidence), expected AS (SELECT '{"table":{"owner":"postgres","rls":true},"columns":[{"column":"id","type":"uuid","udt":"uuid","nullable":"NO","default":"gen_random_uuid()","precision":null,"scale":null},{"column":"title","type":"text","udt":"text","nullable":"NO","default":null,"precision":null,"scale":null},{"column":"slug","type":"text","udt":"text","nullable":"NO","default":null,"precision":null,"scale":null},{"column":"description","type":"text","udt":"text","nullable":"YES","default":null,"precision":null,"scale":null},{"column":"property_type","type":"text","udt":"text","nullable":"NO","default":null,"precision":null,"scale":null},{"column":"listing_type","type":"text","udt":"text","nullable":"NO","default":null,"precision":null,"scale":null},{"column":"price","type":"numeric","udt":"numeric","nullable":"YES","default":null,"precision":14,"scale":2},{"column":"currency","type":"text","udt":"text","nullable":"NO","default":"''GHS''::text","precision":null,"scale":null},{"column":"location","type":"text","udt":"text","nullable":"YES","default":null,"precision":null,"scale":null},{"column":"address","type":"text","udt":"text","nullable":"YES","default":null,"precision":null,"scale":null},{"column":"city","type":"text","udt":"text","nullable":"YES","default":null,"precision":null,"scale":null},{"column":"region","type":"text","udt":"text","nullable":"YES","default":null,"precision":null,"scale":null},{"column":"bedrooms","type":"integer","udt":"int4","nullable":"YES","default":null,"precision":32,"scale":0},{"column":"bathrooms","type":"integer","udt":"int4","nullable":"YES","default":null,"precision":32,"scale":0},{"column":"floor_area","type":"numeric","udt":"numeric","nullable":"YES","default":null,"precision":12,"scale":2},{"column":"land_area","type":"numeric","udt":"numeric","nullable":"YES","default":null,"precision":12,"scale":2},{"column":"status","type":"text","udt":"text","nullable":"NO","default":"''draft''::text","precision":null,"scale":null},{"column":"featured","type":"boolean","udt":"bool","nullable":"NO","default":"false","precision":null,"scale":null},{"column":"created_by","type":"uuid","udt":"uuid","nullable":"YES","default":null,"precision":null,"scale":null},{"column":"created_at","type":"timestamp with time zone","udt":"timestamptz","nullable":"NO","default":"now()","precision":null,"scale":null},{"column":"updated_at","type":"timestamp with time zone","udt":"timestamptz","nullable":"NO","default":"now()","precision":null,"scale":null}],"constraints":[{"table":"enquiries","name":"enquiries_property_id_fkey","definition":"FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE SET NULL"},{"table":"properties","name":"properties_created_by_fkey","definition":"FOREIGN KEY (created_by) REFERENCES profiles(id)"},{"table":"properties","name":"properties_pkey","definition":"PRIMARY KEY (id)"},{"table":"properties","name":"properties_slug_key","definition":"UNIQUE (slug)"},{"table":"properties","name":"properties_status_check","definition":"CHECK ((status = ANY (ARRAY[''draft''::text, ''published''::text, ''sold''::text, ''rented''::text, ''archived''::text])))"},{"table":"property_amenities","name":"property_amenities_property_id_fkey","definition":"FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE CASCADE"},{"table":"property_features","name":"property_features_property_id_fkey","definition":"FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE CASCADE"},{"table":"property_floor_plans","name":"property_floor_plans_property_id_fkey","definition":"FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE CASCADE"},{"table":"property_images","name":"property_images_property_id_fkey","definition":"FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE CASCADE"},{"table":"viewing_requests","name":"viewing_requests_property_id_fkey","definition":"FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE RESTRICT"}],"policies":[{"name":"Administrators can delete properties","roles":["authenticated"],"command":"DELETE","using":"(get_user_role() = ''administrator''::text)","check":null},{"name":"Property managers can create properties","roles":["authenticated"],"command":"INSERT","using":null,"check":"(get_user_role() = ANY (ARRAY[''administrator''::text, ''content_manager''::text]))"},{"name":"Property managers can update properties","roles":["authenticated"],"command":"UPDATE","using":"(get_user_role() = ANY (ARRAY[''administrator''::text, ''content_manager''::text]))","check":"(get_user_role() = ANY (ARRAY[''administrator''::text, ''content_manager''::text]))"},{"name":"Property managers can view all properties","roles":["authenticated"],"command":"SELECT","using":"(get_user_role() = ANY (ARRAY[''administrator''::text, ''content_manager''::text]))","check":null},{"name":"Published properties are publicly viewable","roles":["anon","authenticated"],"command":"SELECT","using":"(status = ''published''::text)","check":null}],"triggers":[{"table":"enquiries","name":"enquiries_set_updated_at","function":"set_updated_at","definition_md5":"12a4155590dbd0dddc0d950df94b1ab7","body_md5":"204b9b9355e61b7541bc0633bbc9294c"},{"table":"properties","name":"properties_set_updated_at","function":"set_updated_at","definition_md5":"cbf55d258f09cc39c7f46caf6c78e916","body_md5":"204b9b9355e61b7541bc0633bbc9294c"},{"table":"viewing_requests","name":"viewing_requests_set_updated_at","function":"set_updated_at","definition_md5":"9ca817b031d82268e5e283a890659f89","body_md5":"204b9b9355e61b7541bc0633bbc9294c"}],"grants":[{"role":"anon","privilege":"DELETE"},{"role":"anon","privilege":"INSERT"},{"role":"anon","privilege":"REFERENCES"},{"role":"anon","privilege":"SELECT"},{"role":"anon","privilege":"TRIGGER"},{"role":"anon","privilege":"TRUNCATE"},{"role":"anon","privilege":"UPDATE"},{"role":"authenticated","privilege":"DELETE"},{"role":"authenticated","privilege":"INSERT"},{"role":"authenticated","privilege":"REFERENCES"},{"role":"authenticated","privilege":"SELECT"},{"role":"authenticated","privilege":"TRIGGER"},{"role":"authenticated","privilege":"TRUNCATE"},{"role":"authenticated","privilege":"UPDATE"},{"role":"service_role","privilege":"DELETE"},{"role":"service_role","privilege":"INSERT"},{"role":"service_role","privilege":"REFERENCES"},{"role":"service_role","privilege":"SELECT"},{"role":"service_role","privilege":"TRIGGER"},{"role":"service_role","privilege":"TRUNCATE"},{"role":"service_role","privilege":"UPDATE"}]}'::jsonb AS e) SELECT k AS check_name, (((e->k) @> (evidence::jsonb->k)) AND ((evidence::jsonb->k) @> (e->k)))::text AS value FROM actual, expected, unnest(ARRAY['table','columns','constraints','policies','triggers','grants']) k UNION ALL SELECT 'legacy_aggregates',(evidence->'legacy_aggregates')::text FROM actual UNION ALL SELECT 'role_permissions',(evidence->'role_permissions')::text FROM actual UNION ALL SELECT 'last_migration',evidence->>'last_migration' FROM actual;
COMMIT;